#include <string>
#include <vector>

std::vector<std::string> split_tags(const std::string& line) {
  std::vector<std::string> tags;
  std::string::size_type start = 0;
  while (true) {
    auto pos = line.find(',', start);
    tags.push_back(line.substr(start, pos - start));
    if (pos == std::string::npos) break;
    start = pos + 1;
  }
  return tags;
}

std::string join_tags(const std::vector<std::string>& tags) {
  std::string out;
  for (std::size_t i = 0; i < tags.size(); ++i) {
    if (i > 0) out += ",";
    out += tags[i];
  }
  return out;
}

std::string tag_key(const std::string& user, int id) {
  return user + ":" + std::to_string(id);
}

