#include <string>
#include <vector>

#include "absl/strings/str_cat.h"
#include "absl/strings/str_join.h"
#include "absl/strings/str_split.h"

std::vector<std::string> split_tags(absl::string_view line) {
  return absl::StrSplit(line, ',', absl::SkipEmpty());
}

std::string join_tags(const std::vector<std::string>& tags) {
  return absl::StrJoin(tags, ",");
}

std::string tag_key(absl::string_view user, int id) {
  return absl::StrCat(user, ":", id);
}

bool has_tag(absl::string_view line, absl::string_view tag) {
  for (absl::string_view part : absl::StrSplit(line, ',', absl::SkipEmpty())) {
    if (part == tag) return true;
  }
  return false;
}
